-- Rename a column from "review_reason" to "status_reason"
ALTER TABLE "product_sourcing_requests" RENAME COLUMN "review_reason" TO "status_reason";
-- Modify "product_sourcing_requests" table
ALTER TABLE "product_sourcing_requests" DROP CONSTRAINT "product_sourcing_requests_review_reason_not_blank", DROP CONSTRAINT "product_sourcing_requests_status_valid", ADD CONSTRAINT "product_sourcing_requests_status_valid" CHECK ((status)::text = ANY ((ARRAY['pending_review'::character varying, 'on_hold'::character varying, 'accepted'::character varying, 'negotiating'::character varying, 'agreed'::character varying, 'converted_to_order'::character varying, 'cancelled'::character varying])::text[])), ADD CONSTRAINT "product_sourcing_requests_status_reason_not_blank" CHECK ((status_reason IS NULL) OR (length(TRIM(BOTH FROM status_reason)) > 0)), ADD CONSTRAINT "product_sourcing_requests_status_reason_required" CHECK (((status)::text <> ALL ((ARRAY['on_hold'::character varying, 'cancelled'::character varying])::text[])) OR (status_reason IS NOT NULL));
